/**
 * Lights Out. Tapping a light flips it and its four neighbours; switch every
 * light off. Boards are generated by pressing random cells on an empty board,
 * so every puzzle is solvable — and the generator knows a solution, which
 * powers the hint button.
 *
 * Puzzle modules export:
 *   { id, howTo: string[], levels: [{ id, label }], create({ rng, level, onChange, onSolved }) }
 * and create() returns { el, restart(), hint?(), status(), share(), destroy() }.
 */
import { h, cx } from '../core/dom.js';
import { play } from '../core/audio.js';

const SIZES = { easy: 3, medium: 4, hard: 5 };

export default {
  id: 'lights',
  howTo: [
    'Tap a light to flip it and the lights directly above, below, left and right of it.',
    'Switch every light off.',
    'Tip: the order of your taps does not matter, and tapping a light twice undoes it.',
  ],
  levels: [{ id: 'easy', label: '3 × 3' }, { id: 'medium', label: '4 × 4' }, { id: 'hard', label: '5 × 5' }],

  create({ rng, level = 'medium', onChange, onSolved }) {
    const n = SIZES[level] || 4;
    const cells = n * n;
    const start = new Array(cells).fill(false);
    const startSolution = new Set();

    const flip = (grid, i) => {
      const r = Math.floor(i / n);
      const c = i % n;
      for (const [dr, dc] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const rr = r + dr;
        const cc = c + dc;
        if (rr >= 0 && rr < n && cc >= 0 && cc < n) grid[rr * n + cc] = !grid[rr * n + cc];
      }
    };

    // Press a random set of distinct cells; that set is a solution.
    const presses = rng.sample(Array.from({ length: cells }, (_, i) => i), Math.max(3, Math.round(cells * 0.4)));
    for (const i of presses) { flip(start, i); startSolution.add(i); }
    if (start.every((v) => !v)) { flip(start, 0); startSolution.add(0); }

    let grid = start.slice();
    let solution = new Set(startSolution);
    let moves = 0;
    let solved = false;
    let hinted = -1;

    const buttons = [];
    const board = h('div.pz-lights', { style: { '--n': n }, role: 'group', 'aria-label': 'Lights Out board' });

    function paint() {
      buttons.forEach((btn, i) => {
        btn.classList.toggle('is-on', grid[i]);
        btn.classList.toggle('is-hint', i === hinted);
        btn.setAttribute('aria-label', `Row ${Math.floor(i / n) + 1}, column ${(i % n) + 1}: ${grid[i] ? 'on' : 'off'}`);
        btn.setAttribute('aria-pressed', String(grid[i]));
      });
    }

    function press(i) {
      if (solved) return;
      flip(grid, i);
      if (solution.has(i)) solution.delete(i); else solution.add(i);
      moves++;
      hinted = -1;
      play('tap');
      paint();
      if (grid.every((v) => !v)) { solved = true; onSolved({ moves, par: startSolution.size }); }
      onChange();
    }

    for (let i = 0; i < cells; i++) {
      const btn = h('button', { type: 'button', class: cx('pz-light') });
      btn.addEventListener('click', () => press(i));
      btn.addEventListener('keydown', (ev) => {
        const step = { ArrowRight: 1, ArrowLeft: -1, ArrowDown: n, ArrowUp: -n }[ev.key];
        if (!step) return;
        ev.preventDefault();
        const j = i + step;
        if (j >= 0 && j < cells && !(Math.abs(step) === 1 && Math.floor(j / n) !== Math.floor(i / n))) buttons[j].focus();
      });
      buttons.push(btn);
      board.appendChild(btn);
    }
    paint();

    return {
      el: board,
      restart() { grid = start.slice(); solution = new Set(startSolution); moves = 0; solved = false; hinted = -1; paint(); onChange(); },
      hint() {
        if (solved || !solution.size) return;
        hinted = Array.from(solution)[0];
        paint();
      },
      status: () => `${moves} tap${moves === 1 ? '' : 's'} · a solution exists in ${startSolution.size}`,
      share: () => `Lights Out ${n}×${n}: solved in ${moves} taps (par ${startSolution.size})`,
      destroy() {},
    };
  },
};
